{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ingress rules lack descriptions",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group has a description, but its dynamically generated ingress rules do not, making the purpose of each firewall rule unclear during review and incident response."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Vault ingress is publicly exposed",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "Every TCP port supplied through var.ingress_ports is accessible from 0.0.0.0/0, potentially exposing Vault services or other sensitive ports directly to the internet."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      description = \"Allow Vault TCP port ${port.value} from within the VPC\"\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [aws_vpc.my_vpc.cidr_block]\n    }\n  }\n}\n",
  "fix_summary": "Added descriptions to all dynamically generated ingress rules and restricted their source from the public internet to the VPC CIDR. The unattached-security-group candidate was not patched because this isolated file may be consumed elsewhere and contains no existing attachable workload resource."
}
